export function isErrorLike(r){return"object"==typeof r&&null!==r&&"name"in r&&"message"in r}export function isErrnoException(r){return isErrorLike(r)&&("errno"in r||"code"in r||"path"in r||"syscall"in r)}export function rewriteError(r,e,o){return r.message=e,r.originalMessage=o??r.originalMessage,r}export function createProtocolErrorMessage(r){let e=r.error.message;return r.error&&"object"==typeof r.error&&"data"in r.error&&(e+=` ${r.error.data}`),e}